import Fastify from 'fastify';
import cors from '@fastify/cors';
import { DemoStore } from '../infrastructure/demo-repositories.js';
import { EventBus } from '../application/event-bus.js';
import { createDomainEvent } from '../domain/contracts.js';
import { calculateInventorySummary, validateUnit } from '../domain/inventory.js';
export function buildApp(store = new DemoStore(), bus = new EventBus()) { const app = Fastify({ logger: false }); app.register(cors, { origin: true }); app.get('/api/health', async () => ({ status: 'ok', dataMode: store.mode })); app.get('/api/dashboard/summary', async () => ({ inventory: calculateInventorySummary(store.units), requests: { pending: store.requests.filter(r => r.status === 'pending').length }, donors: store.donors.length, alerts: calculateInventorySummary(store.units).expiringSoon })); app.get('/api/blood-units', async () => store.units); app.post('/api/blood-units', async (req, res) => { const input = req.body; const errors = validateUnit(input); if (errors.length)
    return res.code(400).send({ code: 'VALIDATION_ERROR', message: 'Unidad inválida', details: errors }); const unit = { ...input, id: crypto.randomUUID(), status: 'available' }; store.units.push(unit); bus.publish(createDomainEvent('BloodUnitRegistered', unit.id, { code: unit.code })); return res.code(201).send(unit); }); app.get('/api/donors', async () => store.donors); app.post('/api/donors', async (req, res) => { const input = req.body; if (!input.name || !input.bloodGroup)
    return res.code(400).send({ code: 'VALIDATION_ERROR', message: 'Nombre y grupo sanguíneo son obligatorios', details: [] }); const donor = { ...input, id: crypto.randomUUID(), documentMasked: '*** *** ' + String(input.document || '0000').slice(-4) }; delete donor.document; store.donors.push(donor); bus.publish(createDomainEvent('DonorRegistered', donor.id, { name: donor.name })); return res.code(201).send(donor); }); app.get('/api/transfusion-requests', async () => store.requests); app.post('/api/transfusion-requests', async (req, res) => { const input = req.body; if (!input.institution || !input.component || !input.bloodGroup || !input.quantity)
    return res.code(400).send({ code: 'VALIDATION_ERROR', message: 'Solicitud incompleta', details: [] }); const item = { ...input, id: crypto.randomUUID(), status: 'pending', createdAt: new Date().toISOString() }; store.requests.push(item); bus.publish(createDomainEvent('TransfusionRequestCreated', item.id, { institution: item.institution, priority: item.priority })); return res.code(201).send(item); }); app.get('/api/events', async () => bus.list().slice(-20).reverse()); return app; }
